  "translit": "Subḥānallāh, wal-ḥamdu lillāh, wa lā ilāha illallāh, wallāhu akbar",
  "fr": "Gloire à Allah, louange à Allah, il n'y a de divinité qu'Allah, et Allah est le plus Grand.",
